import { Button } from '@refy-design/web';
import type { ToastData } from '@refy-design/web';
import { ToastRegion } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useRef } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof ToastRegion>, 'toasts' | 'onDismiss'> = {
    toasts: [],
    onDismiss: () => {},
  };
  const [toasts, setToasts] = useState<ToastData[]>([]);
  const seq = useRef(0);
  function push(toast: Omit<ToastData, 'id'>) {
    seq.current += 1;
    setToasts((t) => [...t, { ...toast, id: `t-${seq.current}` }]);
  }
  const dismiss = (id: string) => setToasts((t) => t.filter((x) => x.id !== id));
  return (
    <div
      style={{
        minHeight: 380,
        padding: 24,
        display: 'flex',
        gap: 8,
        alignItems: 'flex-start',
      }}
    >
      <Button
        onClick={() =>
          push({
            title: 'Review complete',
            description: '84 pages crawled, 12 critical.',
            tone: 'success',
          })
        }
      >
        Success
      </Button>
      <Button
        onClick={() =>
          push({
            title: 'Export failed',
            description: 'The server did not respond.',
            tone: 'danger',
          })
        }
      >
        Error
      </Button>
      <Button
        onClick={() =>
          push({
            title: 'Issue moved to Tasks',
            action: { label: 'Undo', onClick: () => {} },
          })
        }
      >
        With action
      </Button>
      <ToastRegion {...args} toasts={toasts} onDismiss={dismiss} />
    </div>
  );
}

