import { Button } from '@refy-design/web';
import type { ToastData } from '@refy-design/web';
import { ToastRegion } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
const actions = { display: 'flex', flexWrap: 'wrap', gap: 8 } as const;
function ToastExample() {
  const [location, setLocation] = useState('Library'),
    [toasts, setToasts] = useState<ToastData[]>([]);
  return (
    <div style={stack}>
      <p>Material location: {location}</p>
      <div style={actions}>
        <Button
          onClick={() =>
            setToasts([{ id: 'success', title: 'Preferences saved', tone: 'success' }])
          }
        >
          Success
        </Button>
        <Button
          onClick={() =>
            setToasts([
              {
                id: 'error',
                title: 'Could not save',
                description: 'Simulated error to test the message.',
                tone: 'danger',
              },
            ])
          }
        >
          Error
        </Button>
        <Button
          onClick={() => {
            setLocation('File');
            setToasts([
              {
                id: 'move',
                title: 'Material moved to Archive',
                duration: null,
                action: {
                  label: 'Undo',
                  onClick: () => {
                    setLocation('Library');
                    setToasts([]);
                  },
                },
              },
            ]);
          }}
        >
          With action
        </Button>
      </div>
      <ToastRegion
        toasts={toasts}
        onDismiss={(id) => setToasts((rows) => rows.filter((row) => row.id !== id))}
      />
    </div>
  );
}
export function Example() {
  return <ToastExample />;
}
